// Charts of the "Comparing where AI is authorized" section.
// Data: data/chart-data.js (generated by scripts/prepare_data.py).
// Library: D3 v7. Each chart animates the first time it scrolls into view,
// shows a tooltip on hover and redraws itself when the window is resized.

(function () {
  "use strict";

  var DATA = window.CHART_DATA;
  if (!DATA || !window.d3) return;

  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var EASE = d3.easeCubicOut;

  // Colours (validated for colour-vision deficiencies; see css/style.css)
  var GROUP_COLORS = {
    Radiology: "#257de0",
    Cardiovascular: "#f47230",
    Neurology: "#00b894",
    Other: "#c9d3db"
  };
  var PATHWAY_COLORS = { "510(k)": "#257de0", "De Novo": "#f47230", "PMA": "#00b894" };
  var YEAR_COLORS = ["#9dc8f7", "#257de0", "#0e3d7e"];
  var BAR_PARTIAL = "#b6d5f8";
  var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  var fmt = d3.format(",");
  var pct = function (v) { return d3.format(".1f")(v) + "%"; };

  // ---------- Tooltip ----------
  var tooltip = document.getElementById("tooltip");

  function showTooltip(event, html) {
    tooltip.innerHTML = html;
    tooltip.classList.add("is-visible");
    moveTooltip(event);
  }

  function moveTooltip(event) {
    var pad = 16;
    var box = tooltip.getBoundingClientRect();
    var x = event.clientX + pad;
    var y = event.clientY + pad;
    if (x + box.width > window.innerWidth - 8) x = event.clientX - box.width - pad;
    if (y + box.height > window.innerHeight - 8) y = event.clientY - box.height - pad;
    tooltip.style.transform = "translate(" + Math.round(x) + "px," + Math.round(y) + "px)";
  }

  function hideTooltip() {
    tooltip.classList.remove("is-visible");
  }

  function tip(title, lines) {
    return "<strong>" + title + "</strong>" + lines.map(function (l) {
      return "<span class=\"tooltip-meta\">" + l + "</span>";
    }).join("<br>");
  }

  // ---------- Helpers ----------
  function escapeHtml(text) {
    return String(text).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;" }[c];
    });
  }

  // Bar with a rounded data end (4px) and a square baseline.
  function roundedBar(x, y, w, h, r, orientation) {
    r = Math.max(0, Math.min(r, orientation === "up" ? w / 2 : h / 2, orientation === "up" ? h : w));
    if (orientation === "up") {
      return "M" + x + "," + (y + h) + "V" + (y + r) +
        "Q" + x + "," + y + " " + (x + r) + "," + y +
        "H" + (x + w - r) +
        "Q" + (x + w) + "," + y + " " + (x + w) + "," + (y + r) +
        "V" + (y + h) + "Z";
    }
    // "right": baseline on the left
    return "M" + x + "," + y + "H" + (x + w - r) +
      "Q" + (x + w) + "," + y + " " + (x + w) + "," + (y + r) +
      "V" + (y + h - r) +
      "Q" + (x + w) + "," + (y + h) + " " + (x + w - r) + "," + (y + h) +
      "H" + x + "Z";
  }

  function addTable(figureId, headers, rows) {
    var figure = document.getElementById(figureId);
    if (!figure || figure.querySelector(".chart-table")) return;
    var details = document.createElement("details");
    details.className = "chart-table";
    var html = "<summary>Show the data</summary><div class=\"chart-table-scroll\"><table><thead><tr>";
    headers.forEach(function (h) { html += "<th scope=\"col\">" + escapeHtml(h) + "</th>"; });
    html += "</tr></thead><tbody>";
    rows.forEach(function (r) {
      html += "<tr>" + r.map(function (c) { return "<td>" + escapeHtml(c) + "</td>"; }).join("") + "</tr>";
    });
    html += "</tbody></table></div>";
    details.innerHTML = html;
    figure.querySelector("figcaption").insertAdjacentElement("afterend", details);
  }

  function legend(containerId, entries) {
    var el = document.getElementById(containerId);
    if (!el) return;
    el.innerHTML = entries.map(function (e) {
      return "<span class=\"legend-item\"><span class=\"swatch\" data-color=\"" + e.color + "\"></span>" + escapeHtml(e.label) + "</span>";
    }).join("");
    el.querySelectorAll("[data-color]").forEach(function (s) { s.style.background = s.dataset.color; });
  }

  // Registers a chart: draws it (with animation) when it first enters the
  // viewport, then redraws it without animation when its width changes.
  function register(id, draw) {
    var el = document.getElementById(id);
    if (!el) return;
    var drawn = false;
    var lastWidth = 0;

    function render(animate) {
      lastWidth = el.clientWidth;
      el.innerHTML = "";
      draw(el, lastWidth, animate && !reduceMotion);
      drawn = true;
    }

    if ("IntersectionObserver" in window) {
      var observer = new IntersectionObserver(function (entries) {
        if (entries[0].isIntersecting) {
          render(true);
          observer.disconnect();
        }
      }, { threshold: 0.25 });
      observer.observe(el);
    } else {
      render(false);
    }

    var timer;
    window.addEventListener("resize", function () {
      clearTimeout(timer);
      timer = setTimeout(function () {
        if (drawn && Math.abs(el.clientWidth - lastWidth) > 4) render(false);
      }, 150);
    });
  }

  // =====================================================================
  // Extra: radial year clock (one dot per device)
  // =====================================================================
  var clockFilter = "All";
  var clockApi = null;

  function drawClock(el, width, animate) {
    var size = Math.min(width, 620);
    var R = size / 2 - 34;
    var r0 = R * 0.2;
    var years = d3.range(2016, 2027);
    var band = (R - r0) / years.length;
    var dotR = size < 420 ? 1.7 : 2.4;

    var devices = DATA.devices.map(function (d, i) {
      var date = new Date(d[0] + "T00:00:00");
      var year = date.getFullYear();
      var start = new Date(year, 0, 1);
      var days = (new Date(year + 1, 0, 1) - start) / 864e5;
      var angle = ((date - start) / 864e5 / days) * 2 * Math.PI;
      // Deterministic jitter inside the year ring so dots do not pile up.
      var jitter = ((Math.sin(i * 12.9898) * 43758.5453) % 1 + 1) % 1;
      var radius = r0 + (year - 2016) * band + band * (0.15 + 0.7 * jitter);
      return {
        date: d[0], group: d[1], name: d[2], company: d[3], specialty: d[4], year: year,
        x: Math.sin(angle) * radius, y: -Math.cos(angle) * radius
      };
    });

    var svg = d3.select(el).append("svg")
      .attr("viewBox", [-size / 2, -size / 2, size, size].join(" "))
      .attr("aria-hidden", "true");

    // Year rings and month spokes
    var guides = svg.append("g");
    guides.selectAll("circle").data(years.concat([2027])).join("circle")
      .attr("class", "ring")
      .attr("r", function (y) { return r0 + (y - 2016) * band; });
    guides.selectAll("line").data(MONTHS).join("line")
      .attr("class", "spoke")
      .attr("x1", function (m, i) { return Math.sin(i / 12 * 2 * Math.PI) * r0; })
      .attr("y1", function (m, i) { return -Math.cos(i / 12 * 2 * Math.PI) * r0; })
      .attr("x2", function (m, i) { return Math.sin(i / 12 * 2 * Math.PI) * R; })
      .attr("y2", function (m, i) { return -Math.cos(i / 12 * 2 * Math.PI) * R; });
    guides.selectAll("text.month-label").data(MONTHS).join("text")
      .attr("class", "month-label")
      .attr("text-anchor", "middle")
      .attr("dominant-baseline", "middle")
      .attr("x", function (m, i) { return Math.sin((i + 0.5) / 12 * 2 * Math.PI) * (R + 18); })
      .attr("y", function (m, i) { return -Math.cos((i + 0.5) / 12 * 2 * Math.PI) * (R + 18); })
      .text(function (m) { return m; });

    // Dots
    var dots = svg.append("g").selectAll("circle").data(devices).join("circle")
      .attr("class", "mark")
      .attr("r", dotR)
      .attr("fill", function (d) { return GROUP_COLORS[d.group]; })
      .attr("stroke", "#ffffff")
      .attr("stroke-width", 0.6);

    if (animate) {
      dots.attr("cx", 0).attr("cy", 0).attr("opacity", 0)
        .transition()
        .delay(function (d, i) { return (d.year - 2016) * 170 + (i % 40) * 4; })
        .duration(1100)
        .ease(EASE)
        .attr("cx", function (d) { return d.x; })
        .attr("cy", function (d) { return d.y; })
        .attr("opacity", 1);
    } else {
      dots.attr("cx", function (d) { return d.x; }).attr("cy", function (d) { return d.y; });
    }

    // Year labels along the top spoke
    svg.append("g").selectAll("text").data([2016, 2018, 2020, 2022, 2024, 2026]).join("text")
      .attr("class", "ring-label")
      .attr("text-anchor", "middle")
      .attr("dominant-baseline", "middle")
      .attr("x", 0)
      .attr("y", function (y) { return -(r0 + (y - 2016 + 0.5) * band); })
      .text(function (y) { return y; });

    // Centre count
    var centre = svg.append("g").attr("text-anchor", "middle");
    var centreValue = centre.append("text").attr("class", "center-value").attr("y", 4).text(fmt(devices.length));
    centre.append("text").attr("class", "center-label").attr("y", 22).text("devices");

    // Hover: nearest dot (bigger hit target than the dot itself)
    var delaunay = d3.Delaunay.from(devices, function (d) { return d.x; }, function (d) { return d.y; });
    var highlight = svg.append("circle").attr("r", dotR + 3).attr("fill", "none")
      .attr("stroke", "#0e2236").attr("stroke-width", 1.5).attr("opacity", 0);

    svg.append("circle").attr("r", R).attr("fill", "transparent")
      .on("pointermove", function (event) {
        var p = d3.pointer(event, svg.node());
        var i = delaunay.find(p[0], p[1]);
        var d = devices[i];
        if (!d || Math.hypot(d.x - p[0], d.y - p[1]) > 14 ||
            (clockFilter !== "All" && d.group !== clockFilter)) {
          highlight.attr("opacity", 0);
          hideTooltip();
          return;
        }
        highlight.attr("cx", d.x).attr("cy", d.y).attr("opacity", 1);
        showTooltip(event, tip(escapeHtml(d.name), [
          escapeHtml(d.company),
          escapeHtml(d.specialty) + " · " + d3.timeFormat("%d %b %Y")(new Date(d.date + "T00:00:00"))
        ]));
      })
      .on("pointerleave", function () { highlight.attr("opacity", 0); hideTooltip(); });

    function applyFilter(group, smooth) {
      clockFilter = group;
      var selected = group === "All" ? devices.length : devices.filter(function (d) { return d.group === group; }).length;
      var t = smooth && !reduceMotion ? 600 : 0;
      dots.transition().duration(t).ease(EASE)
        .attr("opacity", function (d) { return group === "All" || d.group === group ? 1 : 0.08; })
        .attr("r", function (d) { return group !== "All" && d.group === group ? dotR * 1.25 : dotR; });
      var from = parseInt(centreValue.text().replace(/,/g, ""), 10) || 0;
      centreValue.transition().duration(t).tween("text", function () {
        var interp = d3.interpolateRound(from, selected);
        return function (k) { centreValue.text(fmt(interp(k))); };
      });
    }

    if (clockFilter !== "All") applyFilter(clockFilter, false);
    clockApi = { applyFilter: applyFilter };
  }

  document.querySelectorAll("#fig-clock .filter").forEach(function (button) {
    button.addEventListener("click", function () {
      document.querySelectorAll("#fig-clock .filter").forEach(function (b) {
        b.classList.toggle("is-active", b === button);
        b.setAttribute("aria-pressed", b === button ? "true" : "false");
      });
      clockFilter = button.dataset.group;
      if (clockApi) clockApi.applyFilter(clockFilter, true);
    });
  });

  // =====================================================================
  // 1. Bar chart: authorizations per year
  // =====================================================================
  function drawBar(el, width, animate) {
    var data = DATA.perYear;
    var height = width < 520 ? 300 : 380;
    var m = { top: 30, right: 8, bottom: 34, left: 40 };
    var w = width - m.left - m.right;
    var h = height - m.top - m.bottom;

    var x = d3.scaleBand().domain(data.map(function (d) { return d.year; })).range([0, w]).padding(0.25);
    var y = d3.scaleLinear().domain([0, 350]).range([h, 0]);
    var barW = Math.min(28, x.bandwidth());

    var svg = d3.select(el).append("svg").attr("viewBox", [0, 0, width, height].join(" ")).attr("aria-hidden", "true");
    var g = svg.append("g").attr("transform", "translate(" + m.left + "," + m.top + ")");

    g.append("g").attr("class", "grid")
      .call(d3.axisLeft(y).ticks(5).tickSize(-w).tickFormat(""));
    g.append("g").attr("class", "axis")
      .call(d3.axisLeft(y).ticks(5).tickSize(0).tickPadding(8));
    g.append("g").attr("class", "axis").attr("transform", "translate(0," + h + ")")
      .call(d3.axisBottom(x).tickSize(0).tickPadding(10)
        .tickValues(width < 520 ? data.map(function (d) { return d.year; }).filter(function (yr) { return yr % 2 === 0; }) : null)
        .tickFormat(function (yr) { return yr === 2026 ? "2026*" : yr; }));
    g.append("line").attr("class", "baseline").attr("x1", 0).attr("x2", w).attr("y1", h).attr("y2", h);

    var bars = g.selectAll("path.mark").data(data).join("path")
      .attr("class", "mark")
      .attr("fill", function (d) { return d.partial ? BAR_PARTIAL : GROUP_COLORS.Radiology; })
      .on("pointerenter pointermove", function (event, d) {
        showTooltip(event, tip(d.year + (d.partial ? " (January to March)" : ""), [fmt(d.count) + " devices authorized"]));
      })
      .on("pointerleave", hideTooltip);

    function path(d, k) {
      var bh = (h - y(d.count)) * k;
      return roundedBar(x(d.year) + (x.bandwidth() - barW) / 2, h - bh, barW, bh, 4, "up");
    }

    if (animate) {
      bars.attr("d", function (d) { return path(d, 0); })
        .transition().delay(function (d, i) { return i * 55; }).duration(900).ease(EASE)
        .attrTween("d", function (d) { return function (k) { return path(d, k); }; });
    } else {
      bars.attr("d", function (d) { return path(d, 1); });
    }

    // Selective labels: the start of growth, 2020, the peak and the partial year
    var labelled = data.filter(function (d) { return [2016, 2020, 2025, 2026].indexOf(d.year) !== -1; });
    var labels = g.selectAll("text.value-label").data(labelled).join("text")
      .attr("class", "value-label")
      .attr("text-anchor", "middle")
      .attr("x", function (d) { return x(d.year) + x.bandwidth() / 2; })
      .attr("y", function (d) { return y(d.count) - 8; })
      .text(function (d) { return fmt(d.count); });
    if (animate) {
      labels.attr("opacity", 0).transition().delay(data.length * 55 + 500).duration(500).attr("opacity", 1);
    }
  }

  // =====================================================================
  // 2. Grouped bar chart: top 5 specialties, 2023 / 2024 / 2025
  // =====================================================================
  function drawGrouped(el, width, animate) {
    var years = DATA.grouped.years;
    var rows = DATA.grouped.rows;
    var specialties = Array.from(new Set(rows.map(function (r) { return r.specialty; })));
    var narrow = width < 560;
    var m = { top: 8, right: 44, bottom: 28, left: narrow ? 8 : 190 };
    var groupH = narrow ? 76 : 58;
    var height = specialties.length * groupH + m.top + m.bottom + (narrow ? specialties.length * 18 : 0);
    var w = width - m.left - m.right;

    var y0 = d3.scaleBand().domain(specialties).range([0, height - m.top - m.bottom]).paddingInner(0.22);
    var labelSpace = narrow ? 18 : 0;
    var y1 = d3.scaleBand().domain(years).range([labelSpace, y0.bandwidth()]).padding(0.12);
    var x = d3.scaleLinear().domain([0, 260]).range([0, w]);

    var svg = d3.select(el).append("svg").attr("viewBox", [0, 0, width, height].join(" ")).attr("aria-hidden", "true");
    var g = svg.append("g").attr("transform", "translate(" + m.left + "," + m.top + ")");

    g.append("g").attr("class", "grid").attr("transform", "translate(0," + (height - m.top - m.bottom) + ")")
      .call(d3.axisBottom(x).ticks(5).tickSize(-(height - m.top - m.bottom)).tickFormat(""));
    g.append("g").attr("class", "axis").attr("transform", "translate(0," + (height - m.top - m.bottom) + ")")
      .call(d3.axisBottom(x).ticks(5).tickSize(0).tickPadding(10));

    var groups = g.selectAll("g.group").data(specialties).join("g")
      .attr("class", "group")
      .attr("transform", function (s) { return "translate(0," + y0(s) + ")"; });

    groups.append("text")
      .attr("class", "axis-label")
      .attr("x", narrow ? 0 : -14)
      .attr("y", narrow ? 12 : y0.bandwidth() / 2)
      .attr("text-anchor", narrow ? "start" : "end")
      .attr("dominant-baseline", "middle")
      .attr("font-weight", 600)
      .text(function (s) { return s; });

    groups.append("line").attr("class", "baseline")
      .attr("x1", 0).attr("x2", 0).attr("y1", labelSpace).attr("y2", y0.bandwidth());

    var barH = Math.min(14, y1.bandwidth());
    groups.each(function (spec) {
      var data = rows.filter(function (r) { return r.specialty === spec; });
      var gg = d3.select(this);
      var bars = gg.selectAll("path.mark").data(data).join("path")
        .attr("class", "mark")
        .attr("fill", function (d) { return YEAR_COLORS[years.indexOf(d.year)]; })
        .on("pointerenter pointermove", function (event, d) {
          showTooltip(event, tip(escapeHtml(d.specialty), [d.year + ": " + fmt(d.count) + " devices"]));
        })
        .on("pointerleave", hideTooltip);

      function path(d, k) {
        var bw = Math.max(x(d.count) * k, d.count ? 2 : 0);
        return roundedBar(0, y1(d.year) + (y1.bandwidth() - barH) / 2, bw, barH, 4, "right");
      }

      var labels = gg.selectAll("text.value-label").data(data).join("text")
        .attr("class", "value-label")
        .attr("dominant-baseline", "middle")
        .attr("x", function (d) { return x(d.count) + 6; })
        .attr("y", function (d) { return y1(d.year) + y1.bandwidth() / 2; })
        .text(function (d) { return d.count; });

      if (animate) {
        var base = specialties.indexOf(spec) * 120;
        bars.attr("d", function (d) { return path(d, 0); })
          .transition().delay(function (d, i) { return base + i * 70; }).duration(900).ease(EASE)
          .attrTween("d", function (d) { return function (k) { return path(d, k); }; });
        labels.attr("opacity", 0).transition().delay(base + 700).duration(400).attr("opacity", 1);
      } else {
        bars.attr("d", function (d) { return path(d, 1); });
      }
    });
  }

  // =====================================================================
  // 3. Heatmap: specialty x year
  // =====================================================================
  function drawHeatmap(el, width, animate) {
    var hm = DATA.heatmap;
    var narrow = width < 560;
    var m = { top: 4, right: 4, bottom: 30, left: narrow ? 96 : 190 };
    var cellH = narrow ? 30 : 38;
    var height = hm.rows.length * cellH + m.top + m.bottom;
    var w = width - m.left - m.right;
    var h = height - m.top - m.bottom;

    var x = d3.scaleBand().domain(hm.years).range([0, w]).padding(0.06);
    var y = d3.scaleBand().domain(hm.rows).range([0, h]).padding(0.08);
    var max = d3.max(hm.cells, function (c) { return c.count; });
    var color = d3.scaleSequentialSqrt()
      .domain([0, max])
      .interpolator(d3.interpolateRgbBasis(["#e8f2fc", "#9dc8f7", "#338ced", "#1b64be", "#0e3d7e"]));

    var svg = d3.select(el).append("svg").attr("viewBox", [0, 0, width, height].join(" ")).attr("aria-hidden", "true");
    var g = svg.append("g").attr("transform", "translate(" + m.left + "," + m.top + ")");

    g.append("g").attr("class", "axis").attr("transform", "translate(0," + h + ")")
      .call(d3.axisBottom(x).tickSize(0).tickPadding(10)
        .tickValues(narrow ? hm.years.filter(function (yr) { return yr % 2 === 0; }) : hm.years)
        .tickFormat(function (yr) { return yr === 2026 ? "2026*" : narrow ? "’" + String(yr).slice(2) : yr; }));

    g.append("g").selectAll("text").data(hm.rows).join("text")
      .attr("class", "axis-label")
      .attr("x", -12)
      .attr("y", function (r) { return y(r) + y.bandwidth() / 2; })
      .attr("text-anchor", "end")
      .attr("dominant-baseline", "middle")
      .attr("font-weight", 600)
      .text(function (r) { return narrow && r.length > 13 ? r.split(/[- ]/)[0] : r; });

    var cells = g.selectAll("rect.mark").data(hm.cells).join("rect")
      .attr("class", "mark")
      .attr("x", function (c) { return x(c.year); })
      .attr("y", function (c) { return y(c.specialty); })
      .attr("width", x.bandwidth())
      .attr("height", y.bandwidth())
      .attr("rx", 4)
      .attr("fill", function (c) { return c.count === 0 ? "#f3f6f8" : color(c.count); })
      .on("pointerenter pointermove", function (event, c) {
        showTooltip(event, tip(escapeHtml(c.specialty), [
          (c.year === 2026 ? "2026 (January to March)" : c.year) + ": " + fmt(c.count) + " devices"
        ]));
      })
      .on("pointerleave", hideTooltip);

    if (animate) {
      cells.attr("opacity", 0)
        .attr("transform", function (c) {
          var cx = x(c.year) + x.bandwidth() / 2;
          var cy = y(c.specialty) + y.bandwidth() / 2;
          return "translate(" + cx + "," + cy + ") scale(0.4) translate(" + -cx + "," + -cy + ")";
        })
        .transition()
        .delay(function (c) { return hm.years.indexOf(c.year) * 90 + hm.rows.indexOf(c.specialty) * 25; })
        .duration(700).ease(EASE)
        .attr("opacity", 1)
        .attr("transform", null);
    }

    // Colour legend
    var legendEl = document.getElementById("legend-heatmap");
    if (legendEl && !legendEl.hasChildNodes()) {
      var lw = 220, lh = 10;
      var wrap = d3.select(legendEl).append("div").attr("class", "legend-scale");
      wrap.append("span").text("Devices per year");
      var ls = wrap.append("svg").attr("width", lw + 20).attr("height", 30).attr("aria-hidden", "true");
      var grad = ls.append("defs").append("linearGradient").attr("id", "heat-grad");
      d3.range(0, 1.01, 0.1).forEach(function (t) {
        grad.append("stop").attr("offset", t * 100 + "%").attr("stop-color", color(t * t * max));
      });
      ls.append("rect").attr("x", 10).attr("width", lw).attr("height", lh).attr("rx", 5).attr("fill", "url(#heat-grad)");
      var lx = d3.scaleSqrt().domain([0, max]).range([10, 10 + lw]);
      ls.append("g").attr("class", "axis").attr("transform", "translate(0," + (lh + 2) + ")")
        .call(d3.axisBottom(lx).tickValues([0, 10, 50, 100, 250]).tickSize(0).tickPadding(6));
    }
  }

  // =====================================================================
  // 4. 100% stacked bar chart: regulatory pathway within each specialty
  // =====================================================================
  function drawPathway(el, width, animate) {
    var keys = DATA.pathway.keys;
    var rows = DATA.pathway.rows;
    var narrow = width < 560;
    var m = { top: 4, right: narrow ? 8 : 80, bottom: 30, left: narrow ? 8 : 190 };
    var rowH = narrow ? 58 : 44;
    var height = rows.length * rowH + m.top + m.bottom;
    var w = width - m.left - m.right;
    var h = height - m.top - m.bottom;

    var y = d3.scaleBand().domain(rows.map(function (r) { return r.specialty; })).range([0, h]).padding(0.3);
    var x = d3.scaleLinear().domain([0, 1]).range([0, w]);
    var barH = Math.min(24, y.bandwidth());
    var labelSpace = narrow ? 18 : 0;

    var stacked = [];
    rows.forEach(function (r) {
      var acc = 0;
      keys.forEach(function (k, i) {
        var share = r[k] / r.total;
        stacked.push({ specialty: r.specialty, key: k, count: r[k], total: r.total, x0: acc, x1: acc + share, index: i });
        acc += share;
      });
    });

    var svg = d3.select(el).append("svg").attr("viewBox", [0, 0, width, height].join(" ")).attr("aria-hidden", "true");
    var g = svg.append("g").attr("transform", "translate(" + m.left + "," + m.top + ")");

    g.append("g").attr("class", "axis").attr("transform", "translate(0," + h + ")")
      .call(d3.axisBottom(x).ticks(5, "%").tickSize(0).tickPadding(10));

    g.append("g").selectAll("text").data(rows).join("text")
      .attr("class", "axis-label")
      .attr("x", narrow ? 0 : -14)
      .attr("y", function (r) { return y(r.specialty) + (narrow ? 2 : y.bandwidth() / 2); })
      .attr("text-anchor", narrow ? "start" : "end")
      .attr("dominant-baseline", "middle")
      .attr("font-weight", 600)
      .text(function (r) { return r.specialty + (narrow ? " · n = " + fmt(r.total) : ""); });

    if (!narrow) {
      g.append("g").selectAll("text").data(rows).join("text")
        .attr("class", "annotation")
        .attr("x", w + 12)
        .attr("y", function (r) { return y(r.specialty) + y.bandwidth() / 2; })
        .attr("dominant-baseline", "middle")
        .text(function (r) { return "n = " + fmt(r.total); });
    }

    function segY(d) { return y(d.specialty) + (y.bandwidth() - barH) / 2 + labelSpace / 2; }

    var GAP = 2;
    var segs = g.selectAll("rect.mark").data(stacked.filter(function (d) { return d.count > 0; })).join("rect")
      .attr("class", "mark")
      .attr("y", segY)
      .attr("height", barH)
      .attr("rx", 3)
      .attr("fill", function (d) { return PATHWAY_COLORS[d.key]; })
      .on("pointerenter pointermove", function (event, d) {
        showTooltip(event, tip(escapeHtml(d.specialty) + " · " + d.key, [
          pct((d.x1 - d.x0) * 100) + " (" + fmt(d.count) + " of " + fmt(d.total) + ")"
        ]));
      })
      .on("pointerleave", hideTooltip);

    function segX(d) { return x(d.x0) + (d.x0 > 0 ? GAP / 2 : 0); }
    function segW(d) { return Math.max(1, x(d.x1) - x(d.x0) - (d.x0 > 0 ? GAP / 2 : 0) - (d.x1 < 0.9999 ? GAP / 2 : 0)); }

    if (animate) {
      segs.attr("x", 0).attr("width", 0)
        .transition()
        .delay(function (d) { return rows.map(function (r) { return r.specialty; }).indexOf(d.specialty) * 110 + d.index * 260; })
        .duration(800).ease(EASE)
        .attr("x", segX)
        .attr("width", segW);
    } else {
      segs.attr("x", segX).attr("width", segW);
    }

    // 510(k) share written inside the bar (it always has room)
    var inside = g.selectAll("text.value-label-inside").data(stacked.filter(function (d) { return d.index === 0; })).join("text")
      .attr("class", "value-label-inside")
      .attr("x", 10)
      .attr("y", function (d) { return segY(d) + barH / 2; })
      .attr("dominant-baseline", "middle")
      .text(function (d) { return Math.round((d.x1 - d.x0) * 100) + "%"; });
    if (animate) inside.attr("opacity", 0).transition().delay(1100).duration(500).attr("opacity", 1);
  }

  // =====================================================================
  // 5. Waffle chart: 100 squares by specialty
  // =====================================================================
  var waffleCells = null;

  function drawWaffle(el, width, animate) {
    var groups = DATA.waffle;
    var size = Math.min(width, 460);
    var gap = size < 320 ? 3 : 5;
    var cell = (size - gap * 9) / 10;

    var squares = [];
    groups.forEach(function (gr) {
      for (var i = 0; i < gr.squares; i++) squares.push(gr);
    });

    var svg = d3.select(el).append("svg").attr("viewBox", [0, 0, size, size].join(" ")).attr("aria-hidden", "true");
    waffleCells = svg.selectAll("rect").data(squares).join("rect")
      .attr("class", "mark")
      .attr("x", function (d, i) { return (i % 10) * (cell + gap); })
      .attr("y", function (d, i) { return Math.floor(i / 10) * (cell + gap); })
      .attr("width", cell)
      .attr("height", cell)
      .attr("rx", Math.min(6, cell / 5))
      .attr("fill", function (d) { return GROUP_COLORS[d.group]; })
      .on("pointerenter pointermove", function (event, d) {
        highlightWaffle(d.group);
        showTooltip(event, tip(escapeHtml(d.group), [pct(d.share) + " of devices · " + fmt(d.count)]));
      })
      .on("pointerleave", function () { highlightWaffle(null); hideTooltip(); });

    if (animate) {
      waffleCells
        .attr("opacity", 0)
        .attr("transform", function (d, i) {
          var cx = (i % 10) * (cell + gap) + cell / 2;
          var cy = Math.floor(i / 10) * (cell + gap) + cell / 2;
          return "translate(" + cx + "," + cy + ") scale(0) translate(" + -cx + "," + -cy + ")";
        })
        .transition()
        .delay(function (d, i) { return i * 18; })
        .duration(500)
        .ease(d3.easeBackOut.overshoot(1.6))
        .attr("opacity", 1)
        .attr("transform", null);
    }
  }

  function highlightWaffle(group) {
    if (waffleCells) {
      waffleCells.classed("is-dimmed", function (d) { return group !== null && d.group !== group; });
    }
    document.querySelectorAll("#legend-waffle li").forEach(function (li) {
      li.classList.toggle("is-highlighted", li.dataset.group === group);
    });
  }

  function buildWaffleLegend() {
    var list = document.getElementById("legend-waffle");
    if (!list) return;
    list.innerHTML = DATA.waffle.map(function (gr) {
      return "<li data-group=\"" + escapeHtml(gr.group) + "\">" +
        "<span class=\"swatch\" data-color=\"" + GROUP_COLORS[gr.group] + "\"></span>" +
        "<span>" + escapeHtml(gr.group) + "<span class=\"legend-count\">" + fmt(gr.count) + " devices</span></span>" +
        "<span class=\"legend-share\">" + gr.squares + "</span></li>";
    }).join("");
    list.querySelectorAll("[data-color]").forEach(function (s) { s.style.background = s.dataset.color; });
    list.querySelectorAll("li").forEach(function (li) {
      li.addEventListener("pointerenter", function () { highlightWaffle(li.dataset.group); });
      li.addEventListener("pointerleave", function () { highlightWaffle(null); });
    });
  }

  // =====================================================================
  // Legends, data tables and registration
  // =====================================================================
  legend("legend-grouped", DATA.grouped.years.map(function (yr, i) {
    return { label: yr, color: YEAR_COLORS[i] };
  }));
  legend("legend-pathway", DATA.pathway.keys.map(function (k) {
    return { label: k, color: PATHWAY_COLORS[k] };
  }));
  buildWaffleLegend();

  addTable("fig-bar", ["Year", "Devices authorized"], DATA.perYear.map(function (d) {
    return [d.year + (d.partial ? " (January to March)" : ""), fmt(d.count)];
  }));
  addTable("fig-grouped", ["Specialty"].concat(DATA.grouped.years), Array.from(new Set(DATA.grouped.rows.map(function (r) { return r.specialty; }))).map(function (s) {
    return [s].concat(DATA.grouped.years.map(function (yr) {
      return DATA.grouped.rows.find(function (r) { return r.specialty === s && r.year === yr; }).count;
    }));
  }));
  addTable("fig-heatmap", ["Specialty"].concat(DATA.heatmap.years.map(String)), DATA.heatmap.rows.map(function (r) {
    return [r].concat(DATA.heatmap.years.map(function (yr) {
      return DATA.heatmap.cells.find(function (c) { return c.specialty === r && c.year === yr; }).count;
    }));
  }));
  addTable("fig-pathway", ["Specialty", "510(k)", "De Novo", "PMA", "Total"], DATA.pathway.rows.map(function (r) {
    return [r.specialty, r["510(k)"], r["De Novo"], r.PMA, r.total];
  }));
  addTable("fig-waffle", ["Specialty", "Devices", "Share", "Squares"], DATA.waffle.map(function (gr) {
    return [gr.group, fmt(gr.count), pct(gr.share), gr.squares];
  }));

  register("chart-clock", drawClock);
  register("chart-bar", drawBar);
  register("chart-grouped", drawGrouped);
  register("chart-heatmap", drawHeatmap);
  register("chart-pathway", drawPathway);
  register("chart-waffle", drawWaffle);
})();
